#pragma once

// U3 newstones: NewStoneTypes, Permafrost, BigStoneClusters, VanillaStoneClusters
// (docs/spec/newstones.md).
//
// Blocks, shapes, recipes and loot tables are generated by tools/pack/newstones.ps1. Natively this
// unit gates its content by config (recipes not loaded, blocks left out of the creative inventory),
// gives myalite blocks the tint of their position, adds the mason trades, and generates the big
// stone clusters, the ore pockets and the permafrost underground biomes in Bedrock's chunk
// post-processing (WorldGen.cpp).

#include <cstdint>
#include <functional>
#include <memory>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

class Block;
class BlockPos;
class BlockSource;
class MerchantRecipe;

namespace lp::feature::newstones {

// ---- config (Quark / Zeta config types) ----------------------------------------------------------

/// Zeta DimensionConfig.
struct DimensionsConfig {
    bool                     isBlacklist = false;
    std::vector<std::string> dimensions{"minecraft:overworld"};
};
/// Zeta BiomeTagConfig (the "tags" half of CompoundBiomeConfig).
struct BiomeTagsConfig {
    bool                     isBlacklist = true;
    std::vector<std::string> tags{};
};
/// Zeta StrictBiomeConfig (the "biomes" half of CompoundBiomeConfig).
struct BiomeNamesConfig {
    bool                     isBlacklist = true;
    std::vector<std::string> biomes{};
};
/// Zeta CompoundBiomeConfig: a biome must pass both halves.
struct BiomesConfig {
    BiomeTagsConfig  tags{};
    BiomeNamesConfig biomes{};
};
/// Zeta OrePocketConfig.
struct OrePocketConfig {
    int    minHeight    = 0;
    int    maxHeight    = 60;
    int    clusterSize  = 64;
    double clusterCount = 2.0;
};
/// Quark StoneTypeConfig.
struct StoneTypeConfig {
    DimensionsConfig dimensions{};
    OrePocketConfig  oregenLower{0, 60, 64, 2.0};
    OrePocketConfig  oregenUpper{64, 128, 64, 0.1666666};
};
/// Quark BigStoneClusterConfig / AirStoneClusterConfig (Zeta ClusterSizeConfig + enabled + generateInAir).
struct BigStoneClusterConfig {
    bool             enabled       = true;
    bool             generateInAir = false;
    DimensionsConfig dimensions{};
    BiomesConfig     biomes{};
    int              rarity              = 4;
    int              minYLevel           = 20;
    int              maxYLevel           = 80;
    int              horizontalSize      = 14;
    int              verticalSize        = 14;
    int              horizontalVariation = 9;
    int              verticalVariation   = 9;
};
/// Quark UndergroundStyleConfig (Zeta ClusterSizeConfig; the style is fixed).
struct UndergroundStyleConfig {
    DimensionsConfig dimensions{};
    BiomesConfig     biomes{};
    int              rarity              = 2;
    int              minYLevel           = 105;
    int              maxYLevel           = 140;
    int              horizontalSize      = 72;
    int              verticalSize        = 15;
    int              horizontalVariation = 22;
    int              verticalVariation   = 4;
};

[[nodiscard]] BigStoneClusterConfig bigStoneDefaults(std::vector<std::string> tags);
[[nodiscard]] BigStoneClusterConfig myaliteClusterDefaults();
[[nodiscard]] StoneTypeConfig       endStoneTypeDefaults();
[[nodiscard]] UndergroundStyleConfig permafrostDefaults();

struct NewStonesConfig {
    int version = 1;

    // NewStoneTypes
    bool            enableNewStoneTypes = true;
    bool            enableLimestone     = true;
    bool            enableJasper        = true;
    bool            enableShale         = true;
    bool            enableMyalite       = true;
    StoneTypeConfig newStoneTypesLimestone{};
    StoneTypeConfig newStoneTypesJasper{};
    StoneTypeConfig newStoneTypesShale{};
    StoneTypeConfig newStoneTypesMyalite = endStoneTypeDefaults();
    bool            addNewStonesToMasonTrades = true;

    // Permafrost
    bool                   enablePermafrost   = true;
    UndergroundStyleConfig generationSettings = permafrostDefaults();

    // BigStoneClusters
    bool                     enableBigStoneClusters    = true;
    BigStoneClusterConfig    calcite                   = bigStoneDefaults({"minecraft:is_mountain"});
    BigStoneClusterConfig    bigStoneClustersLimestone = bigStoneDefaults({"c:is_swamp", "minecraft:is_ocean"});
    BigStoneClusterConfig    bigStoneClustersJasper    = bigStoneDefaults({"minecraft:is_badlands", "c:is_sandy"});
    BigStoneClusterConfig    bigStoneClustersShale     = bigStoneDefaults({"c:is_snowy", "c:is_cold"});
    BigStoneClusterConfig    bigStoneClustersMyalite   = myaliteClusterDefaults();
    std::vector<std::string> blocksToReplace{
        "minecraft:stone",
        "minecraft:andesite",
        "minecraft:diorite",
        "minecraft:granite",
        "minecraft:netherrack|minecraft:the_nether",
        "minecraft:end_stone|minecraft:the_end",
        "lepton:limestone",
        "lepton:jasper",
        "lepton:slate"};

    // VanillaStoneClusters (experimental)
    bool                  enableVanillaStoneClusters = false;
    BigStoneClusterConfig granite  = bigStoneDefaults({"minecraft:is_mountain"});
    BigStoneClusterConfig diorite  = bigStoneDefaults({"c:is_savanna", "c:is_jungle", "c:is_mushroom"});
    BigStoneClusterConfig andesite = bigStoneDefaults({"minecraft:is_forest"});
};

[[nodiscard]] NewStonesConfig const& cfg();

// ---- gates ----------------------------------------------------------------------------------------

/// Gate bits: every bit of an id's gate must be enabled for the id to be enabled.
inline constexpr unsigned G_limestone  = 1u << 0; ///< enableNewStoneTypes && enableLimestone
inline constexpr unsigned G_jasper     = 1u << 1; ///< enableNewStoneTypes && enableJasper
inline constexpr unsigned G_shale      = 1u << 2; ///< enableNewStoneTypes && enableShale
inline constexpr unsigned G_myalite    = 1u << 3; ///< enableNewStoneTypes && enableMyalite
inline constexpr unsigned G_permafrost = 1u << 4; ///< enablePermafrost
inline constexpr unsigned G_msv        = 1u << 5; ///< U2 stones.json enableMoreStoneVariants
inline constexpr unsigned G_bricks     = 1u << 6; ///< U2 stones.json enableBricks
inline constexpr unsigned G_chiseled   = 1u << 7; ///< U2 stones.json enableChiseledBricks
inline constexpr unsigned G_pillar     = 1u << 8; ///< U2 stones.json enablePillar
inline constexpr unsigned G_vslab      = 1u << 9; ///< U1 vslabs.json enableVerticalSlabs

/// Options of other units that gate content of this one (true when the file or key is missing).
struct CrossUnit {
    bool moreStoneVariants = true; ///< stones.json: enableMoreStoneVariants
    bool bricks            = true; ///< stones.json: enableBricks
    bool chiseledBricks    = true; ///< stones.json: enableChiseledBricks
    bool pillar            = true; ///< stones.json: enablePillar
    bool verticalSlabs     = true; ///< vslabs.json: enableVerticalSlabs
};
[[nodiscard]] CrossUnit& crossUnit();
void                     refreshCrossUnit();

[[nodiscard]] bool     gateEnabled(unsigned gate);
[[nodiscard]] unsigned blockGate(std::string_view id);
[[nodiscard]] unsigned recipeGate(std::string_view id);
[[nodiscard]] bool     blockEnabled(std::string_view id);
[[nodiscard]] bool     recipeEnabled(std::string_view id);
[[nodiscard]] int      blockCount();
[[nodiscard]] int      recipeCount();
/// Every block id of the unit.
[[nodiscard]] std::vector<std::string_view> blockIds();
/// Stone enabled (`enableNewStoneTypes && enable<S>`), for "limestone", "jasper", "shale", "myalite".
[[nodiscard]] bool stoneEnabled(std::string_view stone);

// ---- myalite tint ---------------------------------------------------------------------------------

inline constexpr std::string_view kTintState = "lepton:tint";
/// Number of tint steps and the step of the items.
[[nodiscard]] int tintSteps();
[[nodiscard]] int defaultTint();
/// Quark's MyaliteColorLogic: the hue before HSBtoRGB, and the colour (0xRRGGBB) at a position.
[[nodiscard]] double   myaliteHue(int x, int y, int z);
[[nodiscard]] uint32_t myaliteColor(int x, int y, int z);
/// The tint step (lepton:tint) for a position.
[[nodiscard]] int tintStep(int x, int y, int z);
/// A myalite-family block id (carries lepton:tint).
[[nodiscard]] bool isTinted(std::string_view id);
/// `block` with the tint of `pos`, or nullptr when it is not a tinted block or already right.
[[nodiscard]] Block const* retinted(Block const& block, BlockPos const& pos);
/// While alive, block changes on this thread are not checked for tints (this unit's own world
/// generation places tinted blocks itself).
struct GenerationScope {
    GenerationScope();
    ~GenerationScope();
    GenerationScope(GenerationScope const&)            = delete;
    GenerationScope& operator=(GenerationScope const&) = delete;

private:
    bool mPrev;
};

// ---- mason trades ---------------------------------------------------------------------------------

/// Quark's journeyman mason offers for the enabled stones (limestone, jasper, shale), applied to a
/// mason's offers (see docs/spec/newstones.md §3): every journeyman (tier 2) offer from index
/// `firstNew` on is replaced with probability Q/(7+Q). `rand01` returns doubles in [0, 1).
/// Returns the number of replaced offers.
int applyMasonTrades(std::vector<MerchantRecipe>& recipes, size_t firstNew, std::function<double()> const& rand01);
/// Number of Quark mason offers with the current config (2 per enabled stone, 0 when off).
[[nodiscard]] int masonOfferCount();

// ---- world generation (WorldGen.cpp) --------------------------------------------------------------

/// Bedrock biome id ("swampland", "minecraft:mesa") -> Java id ("minecraft:swamp", "minecraft:badlands").
[[nodiscard]] std::string javaBiome(std::string_view bedrockBiome);
/// Whether a Java biome id passes a Zeta biome filter (tags resolved to Java 1.21.1 contents).
[[nodiscard]] bool biomeAllowed(std::string_view javaBiomeId, BiomesConfig const& filter);
/// Whether a dimension passes a Zeta dimension filter (0 overworld, 1 nether, 2 end).
[[nodiscard]] bool dimensionAllowed(int dim, DimensionsConfig const& filter);
/// Java's End biome for an End position from the island height value at the chunk.
[[nodiscard]] std::string endBiome(int chunkX, int chunkZ, float islandHeight);

/// A cluster generator of the current config ("calcite", "limestone", "jasper", "shale", "myalite",
/// "granite", "diorite", "andesite").
struct ClusterInfo {
    std::string           name;
    std::string           block; ///< id placed
    BigStoneClusterConfig config;
    int32_t               seedXor = 0; ///< String.hashCode of the Java registry name
    bool                  active  = false;
};
[[nodiscard]] std::vector<ClusterInfo> clusterInfos();

/// Zeta ClusterShape for a size config (horizontal/vertical size and variation) around `src`.
struct ClusterShapeInfo {
    int rx = 0, ry = 0, rz = 0;
};
[[nodiscard]] ClusterShapeInfo clusterShape(int src[3], int hSize, int vSize, int hVar, int vVar);
/// ClusterShape.isInside with the noise seeded by `seedXor`.
[[nodiscard]] bool clusterContains(int32_t seedXor, int const src[3], ClusterShapeInfo const& shape, int const pos[3]);

/// Fills the part of a cluster around `src` that lies in chunk (cx, cz), as the generator does
/// (used by the selftests). Returns the number of blocks placed.
int fillClusterPart(BlockSource& region, BigStoneClusterConfig const& c, int32_t seedXor, Block const& place, int const src[3], int cx, int cz);
/// Quark's PermafrostStyle on one block (the generator's consume step). `rand` is a JavaRandom.
void permafrostFill(BlockSource& region, BlockPos const& pos, void* rand);
/// Zeta's OreGenerator.place at `pos` (the classic ore vein) with `size` blocks. Returns blocks placed.
int placeOrePocket(BlockSource& region, BlockPos const& pos, int size, Block const& place, int64_t seed);

/// Cluster sources (accepted by rarity and biome) within `radius` chunks of chunk (cx, cz) in
/// dimension `dim` of the running level.
struct SourceInfo {
    std::string name;
    int         x = 0, y = 0, z = 0;
    std::string biome;
};
[[nodiscard]] std::vector<SourceInfo> sourcesNear(int dim, int cx, int cz, int radius);
/// "chunks=.. sources=.. placed=.." counters since start (log line / tests).
[[nodiscard]] std::string genStats();
/// Rebuilds the generation plan on next use (world closed).
void invalidateGenPlan();
/// Rebuilds the generation plan now from the current config (server thread: world ready, config
/// reload, selftests that change the config).
void rebuildGenPlan();
void installWorldGen();
void uninstallWorldGen();

} // namespace lp::feature::newstones
